            return parse_boolean(s)
        elif s[0] == 'n':
            return parse_null(s)
        else:
            raise ValueError("Invalid JSON")

    def parse_object(s):
        if s[0] != '{':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the opening brace
        result = {}
        while s and s[0] != '}':
            key = parse_string(s)
            if s[0] != ':':
                raise ValueError("Invalid JSON")
            s = s[1:]  # Remove the colon
            value = parse_value(s)
            result[key] = value
            if s and s[0] == ',':
                s = s[1:]  # Remove the comma
        if s and s[0] != '}':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the closing brace
        return result

    def parse_array(s):
        if s[0] != '[':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the opening bracket
        result = []
        while s and s[0] != ']':
            value = parse_value(s)
            result.append(value)
            if s and s[0] == ',':
                s = s[1:]  # Remove the comma
        if s and s[0] != ']':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the closing bracket
        return result

    def parse_number(s):
        start = 0
